// Side adventures extend the campaign without changing its prerequisites.
const challenge = (id, area, title, requires, task, starter, solution, checks, extra = {}) => ({
  id, area, title, requires, task, starter, solution, checks,
  xp: 100 + requires * 5, coins: 60 + requires * 3, ...extra
});
export const adventures = [
  challenge('delivery', 'mysteries', 'The missing delivery', 0,
    'Repair missing(expected, received). Return how many parcels are still missing, or zero when the delivery is complete.',
    'def missing(expected, received):\n    return received - expected\n\nprint(missing(12, 9))',
    'def missing(expected, received):\n    return max(expected - received, 0)',
    'f = scope.get("missing")\nassert callable(f), "Keep a function named missing."\nfor a,b in [(12,9),(3,3),(4,7),(23,2),(0,0)]:\n    assert f(a,b) == max(a-b,0), "Subtract received from expected; the result cannot be negative."',
    { voice: 'Rowan', intro: 'Twelve parcels were promised. Nine sit by the kitchen door. The ledger insists that minus three are missing. Something small has gone wrong.',
      lesson: 'A function is a reusable recipe. Its parameters are the ingredients you give it. Subtraction finds the difference; max(number, 0) keeps the answer from going below zero.',
      hint: 'expected - received gives the shortage. Wrap that expression in max(..., 0).',
      clues: ['The invoice lists 12 parcels, including three boxes of tea.', 'The kitchen tally confirms 9 parcels actually arrived.', 'A note on the ledger: “An extra parcel is welcome. A negative shortage is not.”'],
      theories: ['The subtraction is backwards.', 'Every parcel weighs three kilograms.', 'The invoice must always be ignored.'], answer: 0,
      ending: 'Three tea parcels turn up on the afternoon cart. Rowan pins your repaired ledger beside the kettle.' }),
  challenge('lanterns', 'mysteries', 'The lantern that stayed dark', 8,
    'Repair lanterns(levels, threshold). Return the zero-based positions of EVERY reading at or above the threshold.',
    'def lanterns(levels, threshold):\n    result = []\n    for i, level in enumerate(levels):\n        if level > threshold:\n            result.append(i)\n        return result',
    'def lanterns(levels, threshold):\n    result = []\n    for i, level in enumerate(levels):\n        if level >= threshold:\n            result.append(i)\n    return result',
    'f = scope.get("lanterns")\nassert callable(f), "Keep lanterns(levels, threshold)."\nfor xs,t in [([3,5,7],5),([],2),([2,2],2),([9,1,10],8),([0],1)]:\n    assert f(xs,t) == [i for i,x in enumerate(xs) if x >= t], "Check equality at the threshold and inspect every reading."',
    { voice: 'Mira', intro: 'The evening lights blink on, but the lane ends in darkness. Mira suspects the controller stopped reading too soon.',
      lesson: 'Indentation controls which block a line belongs to. A return inside a loop ends the function immediately. >= includes the boundary; > excludes it. enumerate gives each reading its position.',
      hint: 'Move return outside the loop. Include readings equal to the threshold.',
      clues: ['The first reading is below the threshold, yet later ones are bright enough.', 'The keeper marked “5 or brighter” on the switch.', 'The controller returns after examining just one lantern.'],
      theories: ['Replace every lantern.', 'The boundary and the early return are both wrong.', 'Only the first reading matters.'], answer: 1,
      ending: 'Warm lights ripple down the entire lane. Mira leaves one glowing in your workshop window.' }),
  challenge('forecast', 'mysteries', 'The suspiciously perfect forecast', 24,
    'Implement baseline(training, inspection). Predict a constant using the mean of training ONLY. inspection is held-out data and must not influence fitting.',
    'def baseline(training, inspection):\n    # Investigate why this seems too accurate.\n    return sum(inspection) / len(inspection)',
    'def baseline(training, inspection):\n    return sum(training) / len(training)',
    'f = scope.get("baseline")\nassert callable(f)\nfor train,test in [([2,4,6],[100]),([3,9],[-50,50]),([0,1,2],[9]),([5],[0,999])]:\n    assert abs(f(train,test) - sum(train)/len(train)) < 1e-8, "Fit on training observations, never held-out inspection values."',
    { voice: 'Elio', intro: 'A weather report predicts yesterday perfectly and tomorrow terribly. Trace where its answers came from.',
      lesson: 'Data leakage happens when information unavailable at prediction time slips into training. Hold out observations to measure generalization. A training mean is a simple baseline to beat.',
      hint: 'Which collection would exist before the inspection happened?',
      clues: ['The forecast was fitted after the inspection labels arrived.', 'Changing the inspection values changes the fitted prediction.', 'The original training log has been left untouched.'],
      theories: ['The model learned a universal rule.', 'More decimal places will fix it.', 'Inspection labels leaked into fitting.'], answer: 2,
      ending: 'Elio publishes an honest report with a separate evaluation column. The village trusts a modest forecast it can check.' }),
  challenge('parcel-shop', 'shop', 'A parcel counter for Bea', 0,
    'Write postage(weight). A parcel costs 2 coins plus 3 coins per kilogram. Weight can be zero or a decimal.',
    'def postage(weight):\n    # Start with the flat fee, then add the weight charge.\n    return 0\n\nprint(postage(2))',
    'def postage(weight):\n    return 2 + 3 * weight',
    'f = scope.get("postage")\nassert callable(f), "Define postage(weight)."\nfor w in [0,0.5,2,7.25]:\n    assert abs(f(w)-(2+3*w)) < 1e-8, "The price is 2 plus 3 times the weight."',
    { voice: 'Bea, the postmistress', intro: 'Bea lends you the old corner shop. Your first commission: a reliable parcel calculator.',
      lesson: 'Multiplication uses *. Python evaluates multiplication before addition. Return sends a result back to the customer; print only displays it.',
      hint: 'Return 2 + 3 * weight.',
      ending: 'Bea puts your calculator on the counter. The little shop is open.',
      functionName: 'postage', customers: [
        { name: 'Bea', request: 'A 2.5 kg parcel of books.', args: [2.5], unit: 'coins postage' },
        { name: 'Rowan', request: 'A 0.5 kg tin of tea.', args: [0.5], unit: 'coins postage' },
        { name: 'Mira', request: 'A 4 kg box of clock parts.', args: [4], unit: 'coins postage' }
      ] }),
  challenge('stock-shop', 'shop', 'Never run out of tea', 8,
    'Write reorder(stock, target). Return a new dictionary with only items below target, mapped to the amount to order. Do not change stock.',
    'def reorder(stock, target):\n    orders = {}\n    # Inspect each item and its count.\n    return orders',
    'def reorder(stock, target):\n    return {name: target-count for name,count in stock.items() if count < target}',
    'f=scope.get("reorder")\nassert callable(f)\nfor stock,t in [({"tea":2,"honey":8},5),({},4),({"beans":0,"milk":3},3),({"cups":12},10)]:\n    before=stock.copy()\n    assert f(stock,t)=={k:t-v for k,v in stock.items() if v<t}, "Only order shortages, with the correct quantities."\n    assert stock==before, "Keep the original stock ledger unchanged."',
    { voice: 'Rowan', intro: 'A full café needs a calm pantry. Help Rowan order just what is missing.',
      lesson: 'A dictionary pairs keys with values. stock.items() lets a loop read both. Build a new dictionary so the original ledger stays reliable.',
      hint: 'For each name, count in stock.items(), add target - count only when count < target.',
      ending: 'Rowan checks your order list each morning before the delivery cart arrives.',
      functionName: 'reorder', customers: [
        { name: 'Rowan', request: 'Bring tea (2) and honey (7) up to 6 each.', args: [{tea:2,honey:7},6], unit: 'to order' },
        { name: 'Bea', request: 'Bring stamps (0) and twine (3) up to 10 each.', args: [{stamps:0,twine:3},10], unit: 'to order' }
      ] }),
  challenge('reviews-shop', 'shop', 'Listening to the village', 16,
    'Write positive_rate(reviews). Return the fraction of ratings at least 4, from 0 to 1. For an empty list return 0.',
    'def positive_rate(reviews):\n    # Decide how to handle an empty list first.\n    pass',
    'def positive_rate(reviews):\n    if not reviews:\n        return 0\n    return sum(1 for rating in reviews if rating >= 4) / len(reviews)',
    'f=scope.get("positive_rate")\nassert callable(f)\nfor xs in [[],[1,4,5,2],[4],[1,2,3],[5,4,4,1,2]]:\n    expected=sum(x>=4 for x in xs)/len(xs) if xs else 0\n    assert abs(f(xs)-expected)<1e-8, "Count ratings at least 4, then divide by all ratings. Handle an empty list."',
    { voice: 'Nell, the bookseller', intro: 'Nell wants to know whether her reading evenings are welcoming. Summarize the ratings, without pretending a tiny sample tells the whole story.',
      lesson: 'A proportion is count / total. Always define empty-input behavior. A high rate from two reviews is much less informative than the same rate from two hundred; this summary is not an AI model.',
      hint: 'Count rating >= 4. Divide by len(reviews), unless it is zero.',
      ending: 'Nell displays the rate alongside the number of responses, and keeps listening.',
      functionName: 'positive_rate', customers: [
        { name: 'Nell', request: 'Four readers rated the evening: 5, 4, 2, 5.', args: [[5,4,2,5]], unit: 'positive fraction (0–1)' },
        { name: 'Mira', request: 'Workshop ratings: 2, 3, 4, 4, 5.', args: [[2,3,4,4,5]], unit: 'positive fraction (0–1)' }
      ] }),
  challenge('seaside-task', 'station', 'The harbour ticket window', 4,
    'Write fare(adults, children). Adults pay 7 coins, children pay 3. Return the total.',
    'def fare(adults, children):\n    return 0',
    'def fare(adults, children):\n    return adults * 7 + children * 3',
    'f=scope.get("fare")\nassert callable(f)\nfor a,c in [(0,0),(2,3),(1,0),(0,4),(5,1)]:\n    assert f(a,c)==a*7+c*3, "Calculate both adult and child tickets."',
    { voice: 'Ada, the harbour keeper', intro: 'Salt air, striped awnings, and a queue for the little ferry. Ada could use a ticket tool.',
      lesson: 'Combining two products makes a useful pricing rule. Test both zero passengers and mixed groups.',
      hint: 'Multiply each passenger count by its own fare, then add.',
      ending: 'Ada stamps a seashell on your travel journal. The ferry leaves on time.' }),
  challenge('snow-task', 'station', 'A warm signal in the snow', 16,
    'Write average_valid(readings). Ignore None (a missing reading), but keep zero and negative temperatures. Return their mean, or None if there are no valid readings.',
    'def average_valid(readings):\n    pass',
    'def average_valid(readings):\n    valid = [x for x in readings if x is not None]\n    return sum(valid) / len(valid) if valid else None',
    'f=scope.get("average_valid")\nassert callable(f)\nfor xs in [[None,-4,0,4],[None],[],[0],[-8,-4,None],[2,5]]:\n    valid=[x for x in xs if x is not None]\n    expected=sum(valid)/len(valid) if valid else None\n    result=f(xs)\n    assert result is None if expected is None else result is not None and abs(result-expected)<1e-8, "Ignore only None. Zero and negative readings are valid."',
    { voice: 'Otto, the station keeper', intro: 'Snow covers the weather sensors. Keep missing readings from hiding a cold snap.',
      lesson: 'Missing data is not the same as zero. Testing “if x” would discard zero by accident. is not None explicitly distinguishes a real reading from a missing one.',
      hint: 'Filter using x is not None, not if x.',
      ending: 'Otto hands you an enamel snowdrop badge and warms another mug beside the stove.' }),
  challenge('forest-task', 'station', 'The academy trial', 32,
    'Write mae(actual, predicted). Return mean absolute error for equally sized, nonempty lists. Raise ValueError for empty or mismatched inputs.',
    'def mae(actual, predicted):\n    # Validate inputs, then calculate the metric.\n    pass',
    'def mae(actual, predicted):\n    if not actual or len(actual) != len(predicted):\n        raise ValueError("Use equally sized nonempty lists")\n    return sum(abs(a-p) for a,p in zip(actual,predicted)) / len(actual)',
    'f=scope.get("mae")\nassert callable(f)\nfor a,p in [([2,4],[1,6]),([0],[-3]),([-2,2],[2,-2]),([1,2,3],[1,2,3])]:\n    assert abs(f(a,p)-sum(abs(x-y) for x,y in zip(a,p))/len(a))<1e-8, "Average absolute errors, not signed errors."\nfor a,p in [([],[]),([1],[]),([1],[1,2])]:\n    try:\n        f(a,p)\n    except ValueError:\n        continue\n    raise AssertionError("Reject empty or mismatched input with ValueError.")',
    { voice: 'Professor Fern', intro: 'Beneath the academy trees, compare a model with the observations it has never seen.',
      lesson: 'Signed errors can cancel. Absolute errors measure distance. MAE stays in the same units as the target. Evaluate held-out observations and compare against a baseline before claiming improvement.',
      hint: 'Check lengths first; use abs(a - p) for each pair.',
      ending: 'Professor Fern gives you a pressed fern bookmark: “A result is only as useful as the way we checked it.”' }),
  challenge('garden-fit', 'garden', 'Teach the sunflowers', 20,
    'Implement fit(samples). Each pair is (sunlight hours, growth cm). Return (slope, intercept) fitted by least squares. Assume at least two distinct sunlight values.',
    'def fit(samples):\n    mean_x = sum(x for x, y in samples) / len(samples)\n    mean_y = sum(y for x, y in samples) / len(samples)\n    numerator = sum((x - mean_x) * (y - mean_y) for x, y in samples)\n    denominator = sum((x - mean_x) ** 2 for x, y in samples)\n    slope = 0  # Replace with numerator / denominator\n    intercept = 0  # Make the line pass through (mean_x, mean_y)\n    return slope, intercept',
    'def fit(samples):\n    mx = sum(x for x,y in samples)/len(samples)\n    my = sum(y for x,y in samples)/len(samples)\n    slope = sum((x-mx)*(y-my) for x,y in samples)/sum((x-mx)**2 for x,y in samples)\n    return slope, my-slope*mx',
    'f=scope.get("fit")\nassert callable(f)\nfor samples in [[(1,3),(2,5),(4,9)],[(0,4),(2,3),(4,2)],[(1,2),(3,2)],[(2,6),(4,9),(6,13)]]:\n    mx=sum(x for x,y in samples)/len(samples); my=sum(y for x,y in samples)/len(samples)\n    slope=sum((x-mx)*(y-my) for x,y in samples)/sum((x-mx)**2 for x,y in samples)\n    m,b=f(samples)\n    assert abs(m-slope)<1e-7 and abs(b-(my-slope*mx))<1e-7, "Fit the slope from the training pairs, then intercept = mean_y - slope * mean_x."',
    { voice: 'Elio', intro: 'Your observations become a small regression model. The plants are fictional; their measurements are a way to practise honest experiments.',
      lesson: 'Least squares fits a straight line: growth = slope × sunlight + intercept. The numerator measures how sunlight and growth vary together. The denominator measures sunlight variation. Held-out beds never enter fit().',
      hint: 'slope = numerator / denominator. intercept = mean_y - slope * mean_x.',
      ending: 'Your model is ready to try in the garden. Check its held-out error before trusting its predictions.' })
];
